contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint amount, address depositor) public payable {
        require(address(this).balance >= amount);

        uint min = c.MinDeposit();
        uint balBefore = address(c).balance;
        uint depBefore = c.balances(depositor);

        if (amount < min) {
            c.Deposit{value: amount}();
            assert(address(c).balance == balBefore);
        } else {
            c.Deposit{value: amount}();
            assert(address(c).balance == balBefore + amount);
            assert(c.balances(depositor) == depBefore + amount);
        }
    }

    receive() external payable {}
}

