contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance");
        require(depositAmount >= 1 ether, "deposit below MinDeposit");

        // Acquire a positive balance for this contract (msg.sender to c).
        c.Deposit{value: depositAmount}();

        uint balBefore = c.balances(address(this));
        uint cBalBefore = address(c).balance;

        // Precondition for the tested rule: the requested amount exceeds the balance,
        // and keep the amount small enough to avoid unrealistic sums while still being
        // an arbitrary over-balance value.
        require(cashOutAmount > balBefore, "amount not over balance");

        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint cBalAfter = address(c).balance;

        assert(
            !reverted &&
            balAfter == balBefore &&
            cBalAfter == cBalBefore
        );
    }

    receive() external payable {}
}

